          {/* Main Content Area - Glass Floating */}
          <main className="flex-1 min-w-0 glass-panel rounded-2xl border-white/5 relative z-10 flex flex-col overflow-hidden bg-black/20">
            {/* Native Scrollable Wrapper with Key Reset */}
            <div 
