  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { SystemBootSequence } from "@/components/SystemBootSequence";

const SIDEBAR_ITEMS = [
  { id: "dashboard", label: "Mission Control", icon: LayoutDashboard },
