    const avgSentiment = analyzes.reduce((sum, a) => sum + a.sentiment, 0) / analyzes.length;
    this.organizationalSentimentTrend = avgSentiment;

    logInfo(this.name, `Szervezeti hangulat: ${(avgSentiment * 100).toFixed(0)}%`);

