/**
 * ProjectConductorAgent - A Brunella projekt "Karmestere"
 *
 * Felelősségek:
 * 1. Projekt állapot folyamatos monitorozása
 * 2. Dokumentáció naprakészen tartása (BRUNELLA.md, konyvtarfa.md, tracks.md)
 * 3. Fejlesztési szálak (tracks) koordinálása
 * 4. Változások detektálása és naplózása
 * 5. Konfliktusok megelőzése több szálon futó fejlesztésnél
 *
 * @author Brunella Core Team
 * @version 1.0.0
 */

import { BaseAgent, AgentContext, AgentResult } from "./BaseAgent.js";
import { logInfo, logError, setAgentStatus } from "../utils/logger.js";
import { generateResponse } from "../core/llm_client.js";
import * as fs from "fs";
import * as path from "path";
import { execSync } from "child_process";

// ============================================================================
// INTERFACES
// ============================================================================

interface ProjectState {
  lastUpdated: string;
  tracks: TrackState[];
  components: ComponentState[];
  recentChanges: ChangeEntry[];
  healthStatus: HealthStatus;
}

interface TrackState {
  id: string;
  name: string;
  status: "proposed" | "active" | "paused" | "completed" | "archived";
  priority: "low" | "medium" | "high" | "critical";
  progress: number; // 0-100
  lastActivity: string;
  blockers: string[];
  assignee?: string;
}

interface ComponentState {
  name: string;
  path: string;
  status: "healthy" | "warning" | "error" | "unknown";
  lastModified: string;
  dependencies: string[];
}

interface ChangeEntry {
  timestamp: string;
  type: "file" | "track" | "config" | "agent" | "documentation";
  action: "created" | "modified" | "deleted" | "moved";
  path: string;
  description: string;
  author?: string;
}

interface HealthStatus {
  overall: "healthy" | "degraded" | "critical";
  buildStatus: boolean;
  testStatus: boolean;
  documentationSync: boolean;
  lastHealthCheck: string;
}

interface DocumentationFile {
  path: string;
  type: "primary" | "conductor" | "technical";
  autoUpdate: boolean;
  lastSync: string;
}

// ============================================================================
// CONSTANTS
// ============================================================================

const PROJECT_ROOT = process.cwd();
const CONDUCTOR_PATH = path.join(PROJECT_ROOT, "conductor");
const STATE_FILE = path.join(CONDUCTOR_PATH, "project_state.json");

const DOCUMENTATION_FILES: DocumentationFile[] = [
  { path: "Brunella.md", type: "primary", autoUpdate: true, lastSync: "" },
  { path: "konyvtarfa.md", type: "technical", autoUpdate: true, lastSync: "" },
  {
    path: "conductor/tracks.md",
    type: "conductor",
    autoUpdate: true,
    lastSync: "",
  },
  {
    path: "conductor/SUMMARY.md",
    type: "conductor",
    autoUpdate: true,
    lastSync: "",
  },
  {
    path: "conductor/workflow.md",
    type: "conductor",
    autoUpdate: false,
    lastSync: "",
  },
  {
    path: "conductor/tech-stack.md",
    type: "conductor",
    autoUpdate: false,
    lastSync: "",
  },
  {
    path: "docs/agents/README_COVERAGE.md",
    type: "technical",
    autoUpdate: true,
    lastSync: "",
  },
];

const MONITORED_DIRECTORIES = [
  "src/agents",
  "src/tools",
  "src/server",
  "src/core",
  "myai",
  "conductor/tracks",
  "cloudflare",
];

// ============================================================================
// AGENT IMPLEMENTATION
// ============================================================================

export class ProjectConductorAgent extends BaseAgent {
  name = "ProjectConductor";
  description =
    "Projekt állapot monitorozás, dokumentáció szinkronizálás, track koordináció";
  role = "Project Manager & Documentation Conductor";

  private projectState: ProjectState;
  private isRunning = false;

  constructor() {
    super();
    this.projectState = this.loadOrInitializeState();
  }

  // --------------------------------------------------------------------------
  // MAIN EXECUTION
  // --------------------------------------------------------------------------

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = context.task?.toLowerCase() || "";
    setAgentStatus(this.name, "working", task);

    try {
      // Command routing
      if (task.includes("status") || task.includes("állapot")) {
        return await this.getProjectStatus();
      }

      if (task.includes("sync") || task.includes("szinkron")) {
        return await this.syncDocumentation();
      }

      if (task.includes("track") && task.includes("create")) {
        const trackName = this.extractTrackName(task);
        return await this.createTrack(trackName, context);
      }

      if (
        task.includes("track") &&
        (task.includes("update") || task.includes("frissít"))
      ) {
        return await this.updateTracks();
      }

      if (task.includes("health") || task.includes("egészség")) {
        return await this.runHealthCheck();
      }

      if (task.includes("changes") || task.includes("változás")) {
        return await this.getRecentChanges();
      }

      if (
        task.includes("foszal") ||
        (task.includes("sync") && task.includes("log"))
      ) {
        return await this.syncFoszal();
      }

      if (
        task.includes("tree") ||
        task.includes("fa") ||
        task.includes("konyvtarfa")
      ) {
        return await this.updateDirectoryTree();
      }

      if (task.includes("full") || task.includes("teljes")) {
        return await this.fullProjectSync();
      }

      if (task.includes("help") || task.includes("segítség") || task === "") {
        return this.showHelp();
      }

      // Default: Chat with Conductor (LLM fallback)
      return await this.chatWithConductor(task);
    } catch (error) {
      logError(this.name, `Hiba: ${error}`);
      setAgentStatus(this.name, "error");
      return {
        success: false,
        message: `ProjectConductor hiba: ${error}`,
        data: null,
      };
    } finally {
      setAgentStatus(this.name, "idle");
    }
  }

  /**
   * Chat with Conductor (LLM alapú válasz)
   */
  private async chatWithConductor(userMessage: string): Promise<AgentResult> {
    logInfo(this.name, `Chat kérés: ${userMessage.slice(0, 50)}...`);

    await this.refreshProjectState();

    // Rövidített állapot
    const tracks = this.projectState.tracks
      .map((t) => `${t.name}: ${t.status} (${t.progress}%)`)
      .join(", ");
    const health = `Build: ${this.projectState.healthStatus?.buildStatus || "unknown"}, Test: ${this.projectState.healthStatus?.testStatus || "unknown"}`;

    const systemPrompt = `
Te vagy a Project Conductor, a Brunella projekt menedzsere.
A feladatod a projekt állapotának felügyelete és a fejlesztési szálak (tracks) koordinálása.
Válaszolj a felhasználó kérdésére a jelenlegi projekt állapot alapján.

JELENLEGI ÁLLAPOT:
- Trackek: ${tracks}
- Health: ${health}
- Utolsó frissítés: ${this.projectState.lastUpdated}
- Legutóbbi változás: ${this.projectState.recentChanges[0]?.description || "Nincs"}

A Válaszod legyen rövid, tömör, és szakmai. Markdown formázást használhatsz.
`;

    try {
      const response = await generateResponse(
        `${systemPrompt}\n\nUser: ${userMessage}\nConductor:`,
        "ollama",
      ); // Prefer local or routed

      return {
        success: true,
        message: response,
        data: { text: response },
      };
    } catch (error: any) {
      return {
        success: false,
        message: `Nem tudtam válaszolni: ${error.message}`,
        data: null,
      };
    }
  }

  // --------------------------------------------------------------------------
  // CORE FUNCTIONS
  // --------------------------------------------------------------------------

  /**
   * Teljes projekt státusz lekérdezése
   */
  private async getProjectStatus(): Promise<AgentResult> {
    logInfo(this.name, "Projekt státusz lekérdezése...");

    await this.refreshProjectState();

    const activeTracks = this.projectState.tracks.filter(
      (t) => t.status === "active",
    );
    const completedTracks = this.projectState.tracks.filter(
      (t) => t.status === "completed",
    );
    const recentChanges = (this.projectState.recentChanges || []).slice(0, 10);

    const statusReport = `
