  private async refreshProjectState(): Promise<void> {
    // Komponensek frissítése
    this.projectState.components = MONITORED_DIRECTORIES.map((dir) => {
      const fullPath = path.join(PROJECT_ROOT, dir);
      const exists = fs.existsSync(fullPath);
      return {
        name: dir.split("/").pop() || dir,
        path: dir,
        status: exists ? "healthy" : "error",
        lastModified: exists ? fs.statSync(fullPath).mtime.toISOString() : "",
        dependencies: [],
      } as ComponentState;
    });
  }

  private addChangeEntry(
    type: ChangeEntry["type"],
    action: ChangeEntry["action"],
    path: string,
    description: string,
  ): void {
    // Inicializálás ha undefined
    if (!this.projectState.recentChanges) {
      this.projectState.recentChanges = [];
    }

    this.projectState.recentChanges.unshift({
      timestamp: new Date().toISOString(),
      type,
      action,
      path,
      description,
    });

    // Csak az utolsó 100 változást tartjuk meg
    if (this.projectState.recentChanges.length > 100) {
      this.projectState.recentChanges = this.projectState.recentChanges.slice(
        0,
        100,
      );
    }
  }

  private generateDirectoryTree(
    dir: string,
    depth: number,
    maxDepth: number,
  ): string {
    if (depth >= maxDepth) return "";

    const items = fs
      .readdirSync(dir)
      .filter(
        (item) =>
          !item.startsWith(".") &&
          !["node_modules", "build", ".venv", "__pycache__", ".git"].includes(
            item,
          ),
      );

    let tree = "";
    const indent = "│   ".repeat(depth);

    items.forEach((item, index) => {
      const isLast = index === items.length - 1;
      const prefix = isLast ? "└── " : "├── ";
      const itemPath = path.join(dir, item);
      const isDir = fs.statSync(itemPath).isDirectory();

      tree += `${indent}${prefix}${item}${isDir ? "/" : ""}\n`;

      if (isDir && depth < maxDepth - 1) {
        tree += this.generateDirectoryTree(itemPath, depth + 1, maxDepth);
      }
    });

    return tree;
  }

  private extractTrackName(task: string): string {
    const match = task.match(/create\s+(?:track\s+)?["']?([^"']+)["']?/i);
    return match?.[1] || "unnamed_track";
  }

  private extractTrackNameFromContent(content: string): string | null {
    const explicit = content.match(/^#\s*Track:\s*(.+)$/m);
    if (explicit?.[1]?.trim()) return explicit[1].trim();

    const heading = content.match(/^#\s+(.+)$/m);
    return heading?.[1]?.trim() || null;
  }

  private parseStatus(status: string): TrackState["status"] {
    const map: Record<string, TrackState["status"]> = {
      proposed: "proposed",
      active: "active",
      "in progress": "active",
      paused: "paused",
      completed: "completed",
      done: "completed",
      archived: "archived",
    };
    return map[status.toLowerCase()] || "active";
  }

  private parsePriority(priority: string): TrackState["priority"] {
    const map: Record<string, TrackState["priority"]> = {
      low: "low",
      medium: "medium",
      high: "high",
      critical: "critical",
    };
    return map[priority.toLowerCase()] || "medium";
  }

  private getRecentChanges(): AgentResult {
    return {
      success: true,
      message: "Legutóbbi változások",
      data: { changes: this.projectState.recentChanges.slice(0, 20) },
    };
  }

  private showHelp(): AgentResult {
    const helpText = `
# ProjectConductor Agent - Súgó

## Elérhető parancsok:

| Parancs | Leírás |
|---------|--------|
| \`status\` / \`állapot\` | Projekt státusz lekérdezése |
| \`sync\` / \`szinkron\` | Dokumentáció szinkronizálás |
| \`foszal\` / \`sync log\` | FOSZAL logok szinkronizálása a Trackekkel |
| \`track create [név]\` | Új track létrehozása |
| \`track update\` | Track-ek frissítése |
| \`health\` | Health check futtatása |
| \`changes\` | Legutóbbi változások |
| \`tree\` / \`konyvtarfa\` | Könyvtárfa frissítése |
| \`full\` / \`teljes\` | Teljes projekt szinkronizálás |

## Példák:

\`\`\`
ProjectConductor status
ProjectConductor track create "Cloudflare Integration"
ProjectConductor sync
ProjectConductor full
\`\`\`
`;

    return {
      success: true,
      message: "ProjectConductor súgó",
      data: { help: helpText },
    };
  }
}

export default ProjectConductorAgent;

resultDisplay.newContent:
/**
 * ProjectConductorAgent - A Brunella projekt "Karmestere"
 *
 * Felelősségek:
 * 1. Projekt állapot folyamatos monitorozása
 * 2. Dokumentáció naprakészen tartása (BRUNELLA.md, konyvtarfa.md, tracks.md)
 * 3. Fejlesztési szálak (tracks) koordinálása
 * 4. Változások detektálása és naplózása
 * 5. Konfliktusok megelőzése több szálon futó fejlesztésnél
 *
 * @author Brunella Core Team
 * @version 1.0.0
 */

import { BaseAgent, AgentContext, AgentResult } from "./BaseAgent.js";
import { logInfo, logError, setAgentStatus } from "../utils/logger.js";
import { generateResponse } from "../core/llm_client.js";
import * as fs from "fs";
import * as path from "path";
import { execSync } from "child_process";

// ============================================================================
// INTERFACES
// ============================================================================

interface ProjectState {
  lastUpdated: string;
  tracks: TrackState[];
  components: ComponentState[];
  recentChanges: ChangeEntry[];
  healthStatus: HealthStatus;
}

interface TrackState {
  id: string;
  name: string;
  status: "proposed" | "active" | "paused" | "completed" | "archived";
  priority: "low" | "medium" | "high" | "critical";
  progress: number; // 0-100
  lastActivity: string;
  blockers: string[];
  assignee?: string;
}

interface ComponentState {
  name: string;
  path: string;
  status: "healthy" | "warning" | "error" | "unknown";
  lastModified: string;
  dependencies: string[];
}

interface ChangeEntry {
  timestamp: string;
  type: "file" | "track" | "config" | "agent" | "documentation";
  action: "created" | "modified" | "deleted" | "moved";
  path: string;
  description: string;
  author?: string;
}

interface HealthStatus {
  overall: "healthy" | "degraded" | "critical";
  buildStatus: boolean;
  testStatus: boolean;
  documentationSync: boolean;
  lastHealthCheck: string;
}

interface DocumentationFile {
  path: string;
  type: "primary" | "conductor" | "technical";
  autoUpdate: boolean;
  lastSync: string;
}

// ============================================================================
// CONSTANTS
// ============================================================================

const PROJECT_ROOT = process.cwd();
const CONDUCTOR_PATH = path.join(PROJECT_ROOT, "conductor");
const STATE_FILE = path.join(CONDUCTOR_PATH, "project_state.json");

const DOCUMENTATION_FILES: DocumentationFile[] = [
  { path: "Brunella.md", type: "primary", autoUpdate: true, lastSync: "" },
  { path: "konyvtarfa.md", type: "technical", autoUpdate: true, lastSync: "" },
  {
    path: "conductor/tracks.md",
    type: "conductor",
    autoUpdate: true,
    lastSync: "",
  },
  {
    path: "conductor/SUMMARY.md",
    type: "conductor",
    autoUpdate: true,
    lastSync: "",
  },
  {
    path: "conductor/workflow.md",
    type: "conductor",
    autoUpdate: false,
    lastSync: "",
  },
  {
    path: "conductor/tech-stack.md",
    type: "conductor",
    autoUpdate: false,
    lastSync: "",
  },
  {
    path: "docs/agents/README_COVERAGE.md",
    type: "technical",
    autoUpdate: true,
    lastSync: "",
  },
];

const MONITORED_DIRECTORIES = [
  "src/agents",
  "src/tools",
  "src/server",
  "src/core",
  "myai",
  "conductor/tracks",
  "cloudflare",
];

// ============================================================================
// AGENT IMPLEMENTATION
// ============================================================================

export class ProjectConductorAgent extends BaseAgent {
  name = "ProjectConductor";
  description =
    "Projekt állapot monitorozás, dokumentáció szinkronizálás, track koordináció";
  role = "Project Manager & Documentation Conductor";

  private projectState: ProjectState;
  private isRunning = false;

  constructor() {
    super();
    this.projectState = this.loadOrInitializeState();
  }

  // --------------------------------------------------------------------------
  // MAIN EXECUTION
  // --------------------------------------------------------------------------

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = context.task?.toLowerCase() || "";
    setAgentStatus(this.name, "working", task);

    try {
      // Command routing
      if (task.includes("status") || task.includes("állapot")) {
        return await this.getProjectStatus();
      }

      if (task.includes("sync") || task.includes("szinkron")) {
        return await this.syncDocumentation();
      }

      if (task.includes("track") && task.includes("create")) {
        const trackName = this.extractTrackName(task);
        return await this.createTrack(trackName, context);
      }

      if (
        task.includes("track") &&
        (task.includes("update") || task.includes("frissít"))
      ) {
        return await this.updateTracks();
      }

      if (task.includes("health") || task.includes("egészség")) {
        return await this.runHealthCheck();
      }

      if (task.includes("changes") || task.includes("változás")) {
        return await this.getRecentChanges();
      }

      if (
        task.includes("foszal") ||
        (task.includes("sync") && task.includes("log"))
      ) {
        return await this.syncFoszal();
      }

      if (
        task.includes("tree") ||
        task.includes("fa") ||
        task.includes("konyvtarfa")
      ) {
        return await this.updateDirectoryTree();
      }

      if (task.includes("full") || task.includes("teljes")) {
        return await this.fullProjectSync();
      }

      if (task.includes("help") || task.includes("segítség") || task === "") {
        return this.showHelp();
      }

      // Default: Chat with Conductor (LLM fallback)
      return await this.chatWithConductor(task);
    } catch (error) {
      logError(this.name, `Hiba: ${error}`);
      setAgentStatus(this.name, "error");
      return {
        success: false,
        message: `ProjectConductor hiba: ${error}`,
        data: null,
      };
    } finally {
      setAgentStatus(this.name, "idle");
    }
  }

  /**
   * Chat with Conductor (LLM alapú válasz)
   */
  private async chatWithConductor(userMessage: string): Promise<AgentResult> {
    logInfo(this.name, `Chat kérés: ${userMessage.slice(0, 50)}...`);

    await this.refreshProjectState();

    // Rövidített állapot
    const tracks = this.projectState.tracks
      .map((t) => `${t.name}: ${t.status} (${t.progress}%)`)
      .join(", ");
    const health = `Build: ${this.projectState.healthStatus?.buildStatus || "unknown"}, Test: ${this.projectState.healthStatus?.testStatus || "unknown"}`;

    const systemPrompt = `
Te vagy a Project Conductor, a Brunella projekt menedzsere.
A feladatod a projekt állapotának felügyelete és a fejlesztési szálak (tracks) koordinálása.
Válaszolj a felhasználó kérdésére a jelenlegi projekt állapot alapján.

JELENLEGI ÁLLAPOT:
- Trackek: ${tracks}
- Health: ${health}
- Utolsó frissítés: ${this.projectState.lastUpdated}
- Legutóbbi változás: ${this.projectState.recentChanges[0]?.description || "Nincs"}

A Válaszod legyen rövid, tömör, és szakmai. Markdown formázást használhatsz.
`;

    try {
      const response = await generateResponse(
        `${systemPrompt}\n\nUser: ${userMessage}\nConductor:`,
        "ollama",
      ); // Prefer local or routed

      return {
        success: true,
        message: response,
        data: { text: response },
      };
    } catch (error: any) {
      return {
        success: false,
        message: `Nem tudtam válaszolni: ${error.message}`,
        data: null,
      };
    }
  }

  // --------------------------------------------------------------------------
  // CORE FUNCTIONS
  // --------------------------------------------------------------------------

  /**
   * Teljes projekt státusz lekérdezése
   */
  private async getProjectStatus(): Promise<AgentResult> {
    logInfo(this.name, "Projekt státusz lekérdezése...");

    await this.refreshProjectState();

    const activeTracks = this.projectState.tracks.filter(
      (t) => t.status === "active",
    );
    const completedTracks = this.projectState.tracks.filter(
      (t) => t.status === "completed",
    );
    const recentChanges = (this.projectState.recentChanges || []).slice(0, 10);

    const statusReport = `
# 📊 Projekt Státusz Jelentés

**Generálva:** ${new Date().toISOString()}
**Utolsó frissítés:** ${this.projectState.lastUpdated}

## 🏥 Egészségi Állapot
- **Összesített:** ${this.projectState.healthStatus?.overall === "healthy" ? "✅ Egészséges" : "⚠️ " + (this.projectState.healthStatus?.overall || "unknown")}
- **Build:** ${this.projectState.healthStatus?.buildStatus ? "✅" : "❌"}
- **Tesztek:** ${this.projectState.healthStatus?.testStatus ? "✅" : "❌"}
- **Dokumentáció szinkron:** ${this.projectState.healthStatus?.documentationSync ? "✅" : "❌"}

## 🚀 Aktív Fejlesztési Szálak (${activeTracks.length})
${activeTracks.map((t) => `- **${t.name}** [${t.priority.toUpperCase()}] - ${t.progress}% ${(t.blockers?.length || 0) > 0 ? "⚠️ Blokkolók: " + t.blockers.join(", ") : ""}`).join("\n")}

## ✅ Lezárt Szálak (${completedTracks.length})
${completedTracks
  .slice(0, 5)
  .map((t) => `- ${t.name}`)
  .join("\n")}

## 📝 Legutóbbi Változások
${recentChanges.map((c) => `- [${c.timestamp.slice(0, 10)}] ${c.action}: ${c.path}`).join("\n")}

## 📁 Komponens Állapotok
${(this.projectState.components || []).map((c) => `- **${c.name}:** ${c.status === "healthy" ? "✅" : c.status === "warning" ? "⚠️" : "❌"}`).join("\n")}
`;

    return {
      success: true,
      message: "Projekt státusz sikeresen lekérdezve",
      data: {
        report: statusReport,
        state: this.projectState,
      },
    };
  }

  /**
   * Dokumentáció szinkronizálása
   */
  private async syncDocumentation(): Promise<AgentResult> {
    logInfo(this.name, "Dokumentáció szinkronizálás indítása...");

    const results: string[] = [];

    for (const doc of DOCUMENTATION_FILES) {
      if (!doc.autoUpdate) continue;

      try {
        const fullPath = path.join(PROJECT_ROOT, doc.path);

        if (doc.path === "konyvtarfa.md") {
          await this.updateDirectoryTree();
          results.push(`✅ ${doc.path} frissítve`);
        } else if (doc.path === "conductor/tracks.md") {
          await this.updateTracksFile();
          results.push(`✅ ${doc.path} frissítve`);
        } else if (doc.path === "Brunella.md") {
          await this.updateBrunellaFile();
          results.push(`✅ ${doc.path} frissítve`);
        } else if (doc.path === "conductor/SUMMARY.md") {
          await this.updateSummaryFile();
          results.push(`✅ ${doc.path} frissítve`);
        } else if (doc.path === "docs/agents/README_COVERAGE.md") {
          await this.updateAgentDocumentationCoverage();
          results.push(`✅ ${doc.path} frissítve`);
        }

        doc.lastSync = new Date().toISOString();
      } catch (error) {
        results.push(`❌ ${doc.path}: ${error}`);
      }
    }

    this.saveState();

    return {
      success: true,
      message: "Dokumentáció szinkronizálás befejezve",
      data: { results },
    };
  }

  /**
   * Új track létrehozása
   */
  private async createTrack(
    name: string,
    context: AgentContext,
  ): Promise<AgentResult> {
    const trackId = `${name.toLowerCase().replace(/\s+/g, "_")}_${new Date().toISOString().slice(0, 10).replace(/-/g, "")}`;
    const trackDir = path.join(CONDUCTOR_PATH, "tracks", trackId);

    logInfo(this.name, `Új track létrehozása: ${trackId}`);

    // Mappa létrehozása
    if (!fs.existsSync(trackDir)) {
      fs.mkdirSync(trackDir, { recursive: true });
    }

    // plan.md létrehozása
    const planContent = `# Track: ${name}

**ID:** \`${trackId}\`
**Státusz:** 🟡 Active
**Prioritás:** MEDIUM
**Létrehozva:** ${new Date().toISOString()}

---

## 🎯 Célok

[Írd le a track céljait]

---

## 📋 Feladatok

- [ ] Feladat 1
- [ ] Feladat 2
- [ ] Feladat 3

---

## ✅ Elfogadási Kritériumok

- [ ] Kritérium 1
- [ ] Kritérium 2

---

## 📝 Napló

### ${new Date().toISOString().slice(0, 10)}
- Track létrehozva
`;

    fs.writeFileSync(path.join(trackDir, "plan.md"), planContent);

    // Track hozzáadása az állapothoz
    const newTrack: TrackState = {
      id: trackId,
      name,
      status: "active",
      priority: "medium",
      progress: 0,
      lastActivity: new Date().toISOString(),
      blockers: [],
    };

    this.projectState.tracks.push(newTrack);
    this.addChangeEntry("track", "created", trackDir, `Új track: ${name}`);
    this.saveState();

    // tracks.md frissítése
    await this.updateTracksFile();

    return {
      success: true,
      message: `Track sikeresen létrehozva: ${trackId}`,
      data: { track: newTrack, path: trackDir },
    };
  }

  /**
   * Track-ek frissítése
   */
  private async updateTracks(): Promise<AgentResult> {
    logInfo(this.name, "Track-ek frissítése...");

    const tracksDir = path.join(CONDUCTOR_PATH, "tracks");
    const trackDirs = fs
      .readdirSync(tracksDir)
      .filter((f) => fs.statSync(path.join(tracksDir, f)).isDirectory());

    const updatedTracks: TrackState[] = [];

    for (const dir of trackDirs) {
      const metaPath = path.join(tracksDir, dir, "meta.json");
      const trackMdPath = path.join(tracksDir, dir, "track.md");
      const planPath = path.join(tracksDir, dir, "plan.md");

      const existingTrack = this.projectState.tracks.find((t) => t.id === dir);

      // Helper: map P0/P1/P2/P3 → TrackState priority
      const priorityFromP = (p?: string): TrackState["priority"] => {
        const v = (p || "").toLowerCase();
        if (v.includes("p0")) return "critical";
        if (v.includes("p1")) return "high";
        if (v.includes("p2")) return "medium";
        if (v.includes("p3")) return "low";
        return this.parsePriority(p || "medium");
      };

      // 1) Prefer meta.json (structured source of truth)
      if (fs.existsSync(metaPath)) {
        try {
          const raw = fs.readFileSync(metaPath, "utf-8");
          const meta = JSON.parse(raw) as any;

          const id = String(meta.track_id ?? meta.id ?? dir);
          const name = String(meta.title ?? meta.name ?? dir);
          const status = this.parseStatus(String(meta.status ?? "active"));
          const priority = priorityFromP(String(meta.priority ?? "medium"));
          const progress = Number(meta.progress ?? 0);
          const lastActivity = String(
            meta.updated_at ?? meta.updated ?? meta.lastActivity ?? "",
          );

          updatedTracks.push({
            id,
            name,
            status,
            priority,
            progress: Number.isFinite(progress)
              ? Math.max(0, Math.min(100, progress))
              : 0,
            lastActivity:
              lastActivity || fs.statSync(metaPath).mtime.toISOString(),
            blockers:
              (meta.blockers as string[]) ?? existingTrack?.blockers ?? [],
            assignee:
              String(
                meta.assigned_agent ??
                  meta.assignee ??
                  existingTrack?.assignee ??
                  "",
              ) || undefined,
          });

          continue;
        } catch (e) {
          logError(this.name, `meta.json parse hiba (${dir}): ${e}`);
          // fall through to track.md/plan.md
        }
      }

      // 2) Fallback: track.md (common in this repo)
      if (fs.existsSync(trackMdPath)) {
        try {
          const content = fs.readFileSync(trackMdPath, "utf-8");
          const firstHeading = content.match(/^#\s+(.+)$/m)?.[1]?.trim();
          const name =
            this.extractTrackNameFromContent(content) || firstHeading || dir;

          const statusLine = content
            .match(/\*\*Status:\*\*\s*([^\n]+)/i)?.[1]
            ?.trim();
          const priorityLine = content
            .match(/\*\*(Priority|Prioritás):\*\*\s*([^\n]+)/i)?.[2]
            ?.trim();
          const progressLine = content.match(
            /\*\*Progress:\*\*\s*(\d+)%/i,
          )?.[1];

          updatedTracks.push({
            id: dir,
            name,
            status: this.parseStatus(
              statusLine || existingTrack?.status || "active",
            ),
            priority: priorityFromP(
              priorityLine || existingTrack?.priority || "medium",
            ),
            progress: parseInt(
              progressLine || String(existingTrack?.progress ?? 0),
            ),
            lastActivity: fs.statSync(trackMdPath).mtime.toISOString(),
            blockers: existingTrack?.blockers || [],
            assignee: existingTrack?.assignee,
          });

          continue;
        } catch (e) {
          logError(this.name, `track.md parse hiba (${dir}): ${e}`);
          // fall through to plan.md
        }
      }

      // 3) Legacy: plan.md
      if (fs.existsSync(planPath)) {
        const content = fs.readFileSync(planPath, "utf-8");

        // Státusz és progress kinyerése a plan.md-ből
        const statusMatch = content.match(/Státusz:\s*([🟢🟡🔴⏸️✅])\s*(\w+)/u);
        const progressMatch = content.match(/Progress:\s*(\d+)%/);
        const priorityMatch = content.match(/Prioritás:\s*(\w+)/i);

        updatedTracks.push({
          id: dir,
          name: this.extractTrackNameFromContent(content) || dir,
          status: this.parseStatus(
            statusMatch?.[2] || existingTrack?.status || "active",
          ),
          priority: this.parsePriority(
            priorityMatch?.[1] || existingTrack?.priority || "medium",
          ),
          progress: parseInt(
            progressMatch?.[1] || String(existingTrack?.progress ?? 0),
          ),
          lastActivity: fs.statSync(planPath).mtime.toISOString(),
          blockers: existingTrack?.blockers || [],
          assignee: existingTrack?.assignee,
        });
      }
    }

    this.projectState.tracks = updatedTracks;
    this.saveState();
    await this.updateTracksFile();

    return {
      success: true,
      message: `${updatedTracks.length} track frissítve`,
      data: { tracks: updatedTracks },
    };
  }

  /**
   * FOSZAL.md -> Tracks szinkronizálás
   */
  private async syncFoszal(): Promise<AgentResult> {
    logInfo(this.name, "FOSZAL -> Tracks szinkronizálás...");

    try {
      const scriptPath = path.join(
        PROJECT_ROOT,
        "scripts",
        "sync_conductor.py",
      );
      // Próbáljuk először 'python3', majd 'python' paranccsal
      try {
        execSync(`python3 "${scriptPath}"`, {
          cwd: PROJECT_ROOT,
          stdio: "pipe",
        });
      } catch (e) {
        execSync(`python "${scriptPath}"`, {
          cwd: PROJECT_ROOT,
          stdio: "pipe",
        });
      }

      return {
        success: true,
        message: "FOSZAL logok sikeresen szinkronizálva a Trackekkel",
        data: null,
      };
    } catch (error) {
      logError(this.name, `FOSZAL szinkron hiba: ${error}`);
      return {
        success: false,
        message: `FOSZAL szinkron hiba: ${error}`,
        data: null,
      };
    }
  }

  /**
   * Health check futtatása
   */
  private async runHealthCheck(): Promise<AgentResult> {
    logInfo(this.name, "Health check futtatása...");

    const health: HealthStatus = {
      overall: "healthy",
      buildStatus: false,
      testStatus: false,
      documentationSync: true,
      lastHealthCheck: new Date().toISOString(),
    };

    // Build ellenőrzés
    try {
      execSync("npm run build", { cwd: PROJECT_ROOT, stdio: "pipe" });
      health.buildStatus = true;
      logInfo(this.name, "✅ Build sikeres");
    } catch {
      health.buildStatus = false;
      health.overall = "degraded";
      logError(this.name, "❌ Build sikertelen");
    }

    // Test ellenőrzés (gyors)
    try {
      execSync("npm run test -- --passWithNoTests --maxWorkers=1", {
        cwd: PROJECT_ROOT,
        stdio: "pipe",
        timeout: 60000,
      });
      health.testStatus = true;
      logInfo(this.name, "✅ Tesztek sikeresek");
    } catch {
      health.testStatus = false;
      health.overall = "degraded";
      logError(this.name, "❌ Tesztek sikertelenek");
    }

    // Dokumentáció szinkron ellenőrzés
    for (const doc of DOCUMENTATION_FILES.filter((d) => d.autoUpdate)) {
      const fullPath = path.join(PROJECT_ROOT, doc.path);
      if (fs.existsSync(fullPath)) {
        const stat = fs.statSync(fullPath);
        const hoursSinceUpdate =
          (Date.now() - stat.mtime.getTime()) / (1000 * 60 * 60);
        if (hoursSinceUpdate > 24) {
          health.documentationSync = false;
          health.overall =
            health.overall === "healthy" ? "degraded" : health.overall;
        }
      }
    }

    if (!health.buildStatus && !health.testStatus) {
      health.overall = "critical";
    }

    this.projectState.healthStatus = health;
    this.saveState();

    return {
      success: true,
      message: `Health check befejezve: ${health.overall}`,
      data: { health },
    };
  }

  /**
   * Teljes projekt szinkronizálás
   */
  private async fullProjectSync(): Promise<AgentResult> {
    logInfo(this.name, "🔄 Teljes projekt szinkronizálás indítása...");

    const results: string[] = [];

    // 1. Track-ek frissítése
    const trackResult = await this.updateTracks();
    results.push(`Tracks: ${trackResult.message}`);

    // 2. Dokumentáció szinkron
    const docResult = await this.syncDocumentation();
    results.push(`Docs: ${docResult.message}`);

    // 3. Health check
    const healthResult = await this.runHealthCheck();
    results.push(`Health: ${healthResult.message}`);

    // 4. Könyvtárfa frissítés
    const treeResult = await this.updateDirectoryTree();
    results.push(`Tree: ${treeResult.message}`);

    // 5. FOSZAL -> Tracks szinkron
    const foszalResult = await this.syncFoszal();
    results.push(`Foszal: ${foszalResult.message}`);

    // 6. Változások naplózása
    this.addChangeEntry(
      "documentation",
      "modified",
      "project",
      "Teljes projekt szinkronizálás",
    );

    this.projectState.lastUpdated = new Date().toISOString();
    this.saveState();

    return {
      success: true,
      message: "Teljes projekt szinkronizálás befejezve",
      data: { results },
    };
  }

