  /**
   * Agent dokumentáció lefedettségi riport generálása (Living Documentation).
   */
  private async updateAgentDocumentationCoverage(): Promise<AgentResult> {
    const agentsDir = path.join(PROJECT_ROOT, "src", "agents");
    const docsAgentsDir = path.join(PROJECT_ROOT, "docs", "agents");
    const outputPath = path.join(docsAgentsDir, "README_COVERAGE.md");

    if (!fs.existsSync(agentsDir)) {
      return {
        success: false,
        message: "src/agents könyvtár nem található",
        data: null,
      };
    }

    if (!fs.existsSync(docsAgentsDir)) {
      fs.mkdirSync(docsAgentsDir, { recursive: true });
    }

    const agentFiles = fs
      .readdirSync(agentsDir)
      .filter((fileName) => fileName.endsWith("Agent.ts"))
      .filter((fileName) => fileName !== "BaseAgent.ts")
      .sort((a, b) => a.localeCompare(b));

    const bootstrapResult = this.bootstrapMissingAgentDocs(
      agentFiles,
      agentsDir,
      docsAgentsDir,
    );

    const rows: string[] = [];
    let documentedCount = 0;

    for (const fileName of agentFiles) {
      const baseName = fileName.replace(/\.ts$/, "");
      const expectedDoc = `${baseName}.md`;
      const expectedDocPath = path.join(docsAgentsDir, expectedDoc);
      const exists = fs.existsSync(expectedDocPath);

      if (exists) documentedCount += 1;

      rows.push(
        `| ${baseName} | ${exists ? "✅" : "❌"} | ${exists ? `./${expectedDoc}` : "—"} |`,
      );
    }

    const totalAgents = agentFiles.length;
    const coverage = totalAgents === 0 ? 100 : Math.round((documentedCount / totalAgents) * 100);

    const content = `# Agent Documentation Coverage

**Generated:** ${new Date().toISOString()}
**Generator:** ProjectConductorAgent

## Summary

- Agents detected: **${totalAgents}**
- Documented: **${documentedCount}**
- Coverage: **${coverage}%**

## Coverage Table

| Agent | Documentation | Doc Path |
|-------|---------------|----------|
${rows.join("\n") || "| — | — | — |"}

---

This file is auto-generated during \
\`brunella conductor sync\` and serves as living documentation coverage status.
`;

    fs.writeFileSync(outputPath, content, "utf-8");

    return {
      success: true,
      message: "Agent documentation coverage frissítve",
      data: {
        totalAgents,
        documentedCount,
        coverage,
        outputPath,
        bootstrappedDocs: bootstrapResult.created,
        refreshedDocs: bootstrapResult.updated,
      },
    };
  }

  /**
   * Hiányzó agent dokumentációk automatikus bootstrap generálása.
   */
  private bootstrapMissingAgentDocs(
    agentFiles: string[],
    agentsDir: string,
    docsAgentsDir: string,
  ): { created: number; updated: number } {
    let created = 0;
    let updated = 0;

    for (const fileName of agentFiles) {
      const baseName = fileName.replace(/\.ts$/, "");
      const sourcePath = path.join(agentsDir, fileName);
      const docPath = path.join(docsAgentsDir, `${baseName}.md`);

      const source = fs.readFileSync(sourcePath, "utf-8");
      const content = this.generateAgentDocContent(baseName, fileName, source);

      if (!fs.existsSync(docPath)) {
        fs.writeFileSync(docPath, content, "utf-8");
        created += 1;
        continue;
      }

      const existingDoc = fs.readFileSync(docPath, "utf-8");
      if (this.shouldRefreshLegacyAgentDoc(existingDoc)) {
        fs.writeFileSync(docPath, content, "utf-8");
        updated += 1;
      }
    }

    return { created, updated };
  }

  private generateAgentDocContent(
    baseName: string,
    fileName: string,
    source: string,
  ): string {
    const agentName = this.extractAssignedString(source, "name") || baseName;
    const role = this.extractAssignedString(source, "role") || "TBD";
    const description =
      this.extractAssignedString(source, "description") ||
      "Agent-specific documentation not yet finalized.";
    const capabilities = this.extractCapabilities(source);

    return `# ${baseName}

**Agent Name:** \`${agentName}\`
**Source:** \`src/agents/${fileName}\`
**Role:** ${role}

## Description

${description}

## Capabilities

${capabilities.length > 0 ? capabilities.map((c) => `- \`${c}\``).join("\n") : "- _No explicit capabilities listed yet._"}

## Inputs / Outputs

- **Primary input:** Task string + optional context object.
- **Primary output:** Agent result/response object.

## Operational Notes

- Generated automatically by \`ProjectConductorAgent\` during \`conductor sync\`.
- Replace placeholders and expand with concrete examples over time.

## TODO

- [ ] Add real-world usage examples
- [ ] Add failure modes and recovery notes
- [ ] Add integration touchpoints
`;
  }

  private shouldRefreshLegacyAgentDoc(existingDoc: string): boolean {
    return (
      existingDoc.includes("## Purpose") ||
      existingDoc.includes("- Add capabilities and examples")
    );
  }

  private extractAssignedString(source: string, property: string): string | null {
    const directMatch = source.match(
      new RegExp(`${property}\\s*=\\s*['\"]([^'\"]+)['\"]`),
    );
    if (directMatch?.[1]) {
      return directMatch[1].trim();
    }

    const blockMatch = source.match(
      new RegExp(`${property}\\s*=\\s*([\"'\`])([\\s\\S]*?)\\1`),
    );
    if (blockMatch?.[2]) {
      return blockMatch[2].replace(/\s+/g, " ").trim();
    }

    return null;
  }

  private extractCapabilities(source: string): string[] {
    const capabilitiesMatch = source.match(
      /capabilities\s*=\s*\[([\s\S]*?)\]/,
    );
    if (!capabilitiesMatch?.[1]) {
      return [];
    }

    const entries = capabilitiesMatch[1].match(/['\"]([^'\"]+)['\"]/g) || [];
    return entries
      .map((entry) => entry.replace(/['\"]/g, "").trim())
      .filter(Boolean);
  }

  // --------------------------------------------------------------------------
  // HELPER FUNCTIONS
  // --------------------------------------------------------------------------

  private loadOrInitializeState(): ProjectState {
    if (fs.existsSync(STATE_FILE)) {
      try {
        return JSON.parse(fs.readFileSync(STATE_FILE, "utf-8"));
      } catch {
        logError(this.name, "Állapot fájl sérült, újrainicializálás...");
      }
    }

    return {
      lastUpdated: new Date().toISOString(),
      tracks: [],
      components: [],
      recentChanges: [],
      healthStatus: {
        overall: "unknown" as any,
        buildStatus: false,
        testStatus: false,
        documentationSync: false,
        lastHealthCheck: "",
      },
    };
  }

  private saveState(): void {
    this.projectState.lastUpdated = new Date().toISOString();
    fs.writeFileSync(STATE_FILE, JSON.stringify(this.projectState, null, 2));
  }

  private async refreshProjectState(): Promise<void> {
    // Komponensek frissítése
    this.projectState.components = MONITORED_DIRECTORIES.map((dir) => {
      const fullPath = path.join(PROJECT_ROOT, dir);
      const exists = fs.existsSync(fullPath);
      return {
        name: dir.split("/").pop() || dir,
        path: dir,
        status: exists ? "healthy" : "error",
        lastModified: exists ? fs.statSync(fullPath).mtime.toISOString() : "",
        dependencies: [],
      } as ComponentState;
    });
  }

  private addChangeEntry(
    type: ChangeEntry["type"],
    action: ChangeEntry["action"],
    path: string,
    description: string,
  ): void {
    // Inicializálás ha undefined
    if (!this.projectState.recentChanges) {
      this.projectState.recentChanges = [];
    }

    this.projectState.recentChanges.unshift({
      timestamp: new Date().toISOString(),
      type,
      action,
      path,
      description,
    });

    // Csak az utolsó 100 változást tartjuk meg
    if (this.projectState.recentChanges.length > 100) {
      this.projectState.recentChanges = this.projectState.recentChanges.slice(
        0,
        100,
      );
    }
  }

  private generateDirectoryTree(
    dir: string,
    depth: number,
    maxDepth: number,
  ): string {
    if (depth >= maxDepth) return "";

    const items = fs
      .readdirSync(dir)
      .filter(
        (item) =>
          !item.startsWith(".") &&
          !["node_modules", "build", ".venv", "__pycache__", ".git"].includes(
            item,
          ),
      );

    let tree = "";
    const indent = "│   ".repeat(depth);

    items.forEach((item, index) => {
      const isLast = index === items.length - 1;
      const prefix = isLast ? "└── " : "├── ";
      const itemPath = path.join(dir, item);
      const isDir = fs.statSync(itemPath).isDirectory();

      tree += `${indent}${prefix}${item}${isDir ? "/" : ""}\n`;

      if (isDir && depth < maxDepth - 1) {
        tree += this.generateDirectoryTree(itemPath, depth + 1, maxDepth);
      }
    });

    return tree;
  }

  private extractTrackName(task: string): string {
    const match = task.match(/create\s+(?:track\s+)?["']?([^"']+)["']?/i);
    return match?.[1] || "unnamed_track";
  }

  private extractTrackNameFromContent(content: string): string | null {
    const explicit = content.match(/^#\s*Track:\s*(.+)$/m);
    if (explicit?.[1]?.trim()) return explicit[1].trim();

    const heading = content.match(/^#\s+(.+)$/m);
    return heading?.[1]?.trim() || null;
  }

  private parseStatus(status: string): TrackState["status"] {
    const map: Record<string, TrackState["status"]> = {
      proposed: "proposed",
      active: "active",
      "in progress": "active",
      paused: "paused",
      completed: "completed",
      done: "completed",
      archived: "archived",
    };
    return map[status.toLowerCase()] || "active";
  }

  private parsePriority(priority: string): TrackState["priority"] {
    const map: Record<string, TrackState["priority"]> = {
      low: "low",
      medium: "medium",
      high: "high",
      critical: "critical",
    };
    return map[priority.toLowerCase()] || "medium";
  }

  private getRecentChanges(): AgentResult {
    return {
      success: true,
      message: "Legutóbbi változások",
      data: { changes: this.projectState.recentChanges.slice(0, 20) },
    };
  }

  private showHelp(): AgentResult {
    const helpText = `
# ProjectConductor Agent - Súgó

## Elérhető parancsok:

| Parancs | Leírás |
|---------|--------|
| \`status\` / \`állapot\` | Projekt státusz lekérdezése |
| \`sync\` / \`szinkron\` | Dokumentáció szinkronizálás |
| \`foszal\` / \`sync log\` | FOSZAL logok szinkronizálása a Trackekkel |
| \`track create [név]\` | Új track létrehozása |
| \`track update\` | Track-ek frissítése |
| \`health\` | Health check futtatása |
| \`changes\` | Legutóbbi változások |
| \`tree\` / \`konyvtarfa\` | Könyvtárfa frissítése |
| \`full\` / \`teljes\` | Teljes projekt szinkronizálás |

## Példák:

\`\`\`
ProjectConductor status
ProjectConductor track create "Cloudflare Integration"
ProjectConductor sync
ProjectConductor full
\`\`\`
`;

    return {
      success: true,
      message: "ProjectConductor súgó",
      data: { help: helpText },
    };
  }
}

export default ProjectConductorAgent;

