    const healthResult = await this.runHealthCheck();
    results.push(`Health: ${healthResult.message}`);

    // 4. Könyvtárfa frissítés
    const treeResult = await this.updateDirectoryTree();
    results.push(`Tree: ${treeResult.message}`);

