        if (trimmed.toLowerCase().startsWith("/edge")) {
          edgeMode = !edgeMode;
          console.log(
            edgeMode
              ? chalk.cyan("Edge mode enabled (Cloudflare).")
              : chalk.yellow("Edge mode disabled (Local/API)."),
