            if (provider === "gemini")
              modelChoices = [
                "gemini-2.5-flash",
                "gemini-2.0-flash",
                "gemini-flash-latest",
                "gemini-2.5-pro",
              ];
            if (provider === "ollama")
              modelChoices = ["llama3.1:8b", "deepseek-r1:8b", "qwen2.5-coder"];

