      let activeProvider: "ollama" | "gemini" | "github" = "github";
      let activeModel: string = "gpt-4o"; // Updated to valid model

      let edgeMode = false;

      console.log(
        chalk.green(
          `\n✔ Active Model: ${chalk.bold(activeModel)} (${activeProvider})\n`,
        ),
