      {
        type: "list",
        name: "action",
        message: "Local Test Scheduler - Mit szeretnél tenni?",
        choices: [
          { name: "📊 Scheduler státusza és eredmények", value: "status" },
          { name: "🚀 Manuális tesztfuttatás indítása", value: "run" },
