        const content = readFileSync(specPath, "utf-8");
        const updated = content
          .replace(/status:\s+pending|status:\s+active|status:\s+testing/i, "status: completed")
          .replace(/completedAt:.*$/m, `completedAt: ${new Date().toISOString()}`);
