      console.log(chalk.green("✅ Szerver elindítva!"));
      console.log(chalk.cyan("📱 Nyisd meg: http://localhost:3000"));
      console.log(chalk.dim("Kilépéshez: Ctrl+C\n"));
      proc.on("exit", (code) => process.exit(code || 0));
    } else if (action === "push") {
