/**
 * Check Dashboard (Vite dev server)
 */
async function checkDashboard(timeoutMs: number): Promise<ServiceHealth> {
    const name = 'Dashboard';
    const start = Date.now();
    const baseUrl = process.env.DASHBOARD_URL || 'http://localhost:5173';

