program
  .command("run <toolName> [args...]")
  .description("Run an MCP tool")
  .option("--json", "Output raw JSON response")
  .action(
    async (
      toolName: string,
      args: string[] = [],
      cmd?: { opts: () => { json?: boolean } },
    ) => {
      const opts = cmd?.opts?.() ?? {};
      const parsedArgs: Record<string, string> = {};

      for (const arg of args || []) {
        const parts = arg.split("=");
        if (parts.length >= 2) {
          const key = parts[0];
          const value = parts.slice(1).join("=");
          parsedArgs[key] = value;
        } else if (arg.startsWith("{")) {
          try {
          } catch { /* non-critical */ }
        }
      }

      const client = new BrunellaClient();
      try {
        await client.connect();
        const result = await client.callTool(toolName, parsedArgs);

        if (opts.json) {
          console.log(JSON.stringify(result, null, 2));
        } else {
          // @ts-expect-error
          const text = result.content?.[0]?.text;
          if (text) console.log(text);
          else console.log(JSON.stringify(result, null, 2));
        }
      } catch (error: any) {
        console.error(chalk.red("Tool execution failed:"), error.message);
        process.exit(1);
      } finally {
        await client.close();
        process.exit(0);
      }
    },
  );

