              const { execSync } = await import("child_process");
              execSync("node build/cli-jules-interactive.js", {
                stdio: "inherit",
                cwd: process.cwd(),
              });
            } catch (e: any) {
              console.log(chalk.red(`Error launching menu: ${e.message}`));
