    const { AgentArchitect } = await import("./agents/AgentArchitect.js");

    let desc = description;
    if (!desc) {
      const answer = await inquirer.prompt([
        {
          type: "input",
          name: "description",
          message: "Describe the agent (e.g. 'Monitor HackerNews top posts'):",
        },
      ]);
      desc = answer.description;
