  "capabilities": ["web_scraping", "summarization", "monitoring"],
  "triggers": ["hackernews", "hn", "tech_news"]
}

Return ONLY valid JSON, no markdown, no explanation.
`;

      const analysisResult = await generateResponse(analysisPrompt);
