              chalk.dim("  /jules new     - Új Jules task létrehozás"),
            );
            console.log(
              chalk.dim("  /jules sync    - GitHub Jules branch-ek pullolása"),
            );
            console.log(
              chalk.dim("  /jules status  - Sessions + branch-ek státusza"),
            );
            console.log(
              chalk.dim("  /jules menu    - Interaktív menü indítás\n"),
            );
