testsCmd
  .command("results [count]")
  .description("Show recent test run results")
  .action(async (count: string) => {
    const client = new BrunellaClient();
    const limit = parseInt(count || "10");
    const spinner = ora("Fetching test results...").start();
    try {
      await client.connect();
      
      // Fetch results via HTTP (CLI-friendly)
      const response = await fetch("http://localhost:3000/api/tests/results?limit=" + limit);
      spinner.stop();
      
      if (!response.ok) throw new Error("Failed to fetch results");
      
      const data = (await response.json()) as { runs: any[] };
      console.log(chalk.bold(`\n🧪 Recent Test Runs (Last ${limit})\n`));

      if (data.runs.length === 0) {
        console.log(chalk.dim("No test runs found"));
      } else {
        data.runs.forEach((run: any, i: number) => {
          const status = run.status === "passed" ? chalk.green("✓") : chalk.red("✗");
          const duration = run.duration || "N/A";
          console.log(`${i + 1}. ${status} ID: ${chalk.cyan(run.id)} | ${run.passed}✓ ${run.failed}✗ | ${duration}`);
          console.log(`   Started: ${chalk.dim(new Date(run.startedAt).toLocaleString("hu-HU"))}`);
        });
      }
    } catch (e: any) {
      spinner.stop();
      console.error(chalk.red("Error:"), e.message);
    } finally {
      await client.close();
      process.exit(0);
    }
  });

// ════════════════════════════════════════════════════════════════════════════
// HARVEST COMMAND (Tech-Harvester Pipeline)
// ════════════════════════════════════════════════════════════════════════════

const harvestCmd = program
  .command("harvest")
  .description("Run Tech-Harvester pipeline (scrape AI/Tech sources → LanceDB RAG)");

harvestCmd
  .command("run")
  .description("Run full harvest pipeline (harvest → refine → integrate)")
  .option("--mode <mode>", "Harvesting mode (playwright|browser-use)", "playwright")
  .option("--config <path>", "Sources config file", "myai/config/sources.json")
  .action(async (options) => {
    const ora = (await import("ora")).default;
    const chalk = (await import("chalk")).default;

    console.log(chalk.blue("\n╔════════════════════════════════════════════════════════════════╗"));
    console.log(chalk.blue("║") + chalk.bold("           TECH-HARVESTER PIPELINE                          ") + chalk.blue("║"));
    console.log(chalk.blue("╚════════════════════════════════════════════════════════════════╝\n"));

    const spinner = ora("Starting harvest pipeline...").start();

    try {
      const { spawn } = await import("child_process");

      const pythonProcess = spawn("python", [
        "myai/tools/harvest_pipeline.py",
        "--mode", options.mode,
        "--config", options.config,
      ], {
        stdio: "inherit",
      });

      await new Promise((resolve, reject) => {
        pythonProcess.on("close", (code) => {
          if (code === 0) {
            spinner.succeed(chalk.green("Harvest pipeline completed successfully!"));
            resolve(undefined);
          } else {
            spinner.fail(chalk.red(`Harvest pipeline failed with exit code ${code}`));
            reject(new Error(`Exit code ${code}`));
          }
        });

        pythonProcess.on("error", (err) => {
          spinner.fail(chalk.red("Failed to start harvest pipeline"));
          reject(err);
        });
      });

    } catch (error: any) {
      spinner.fail(chalk.red("Harvest pipeline error"));
      console.error(chalk.red(`Error: ${error.message}`));
      process.exit(1);
    }
  });

harvestCmd
  .command("status")
  .description("Show last harvest summary")
  .action(async () => {
    const chalk = (await import("chalk")).default;
    const { readFileSync } = await import("fs");
    const { resolve } = await import("path");

    try {
      const logPath = resolve("logs/harvest_pipeline.log");
      const logContent = readFileSync(logPath, "utf-8");

      // Extract last summary
      const lines = logContent.split("\n").reverse();
      const summaryLines: string[] = [];
      let foundSummary = false;

      for (const line of lines) {
        if (line.includes("HARVEST PIPELINE COMPLETED")) {
          foundSummary = true;
          summaryLines.push(line);
          continue;
        }

        if (foundSummary) {
          summaryLines.push(line);

          if (line.includes("HARVEST PIPELINE STARTING")) {
            break;
          }
        }
      }

      if (summaryLines.length > 0) {
        console.log(chalk.blue("\n" + "═".repeat(80)));
        console.log(chalk.bold("LAST HARVEST SUMMARY"));
        console.log(chalk.blue("═".repeat(80)));
        summaryLines.reverse().forEach((line) => console.log(line));
        console.log(chalk.blue("═".repeat(80) + "\n"));
      } else {
        console.log(chalk.yellow("No harvest summary found. Run 'brunella harvest run' first."));
      }

    } catch (error: any) {
      console.error(chalk.red(`Error reading harvest log: ${error.message}`));
    }
  });

// Interactive Menu (Default)
if (!process.argv.slice(2).length) {
  startInteractiveMenu();
} else {
  program.parse(process.argv);
}

messages.content:
Újraolvastam a `src/cli.ts` fájlt.

A 835. sorban lévő elemzési hiba a következő volt: `F:\mcp-brunella-core\src\cli.ts:835:13 error Parsing error: ',' expected`

Nézzük meg a 835. sort:
```typescript
834 testsCmd
835   .command("status")
```
Ez egy `.command("status")` hívás a `testsCmd` számára.
A "',' expected" hibaüzenet általában hiányzó vesszőre utal egy objektumliterálban vagy tömbben, vagy szintaktikai hibára.

Nézzük meg alaposabban a `testsCmd` blokkot ezen a területen.
```typescript
// ════════════════════════════════════════════════════════════════════════════
// TESTS COMMAND (Test Scheduler)
// ════════════════════════════════════════════════════════════════════════════

const testsCmd = program
  .command("tests")
  .description("Manage test scheduling and results")
  .action(async () => {
    // ... code ...
  });

testsCmd
  .command("status")
  .description("Show test scheduler status and statistics")
  .action(async () => {
    // ... code ...
  });
```
Úgy tűnik, több `testsCmd.command` blokkom is van. Lehet, hogy az egyikből hiányzik egy záró zárójel vagy zárójel.

Közelebbről megnézve a `testsCmd` definícióját:
```typescript
const testsCmd = program
  .command("tests")
  .description("Manage test scheduling and results")
  .action(async () => {
    // ... a lot of code ...
  }); // <--- Itt van az action függvény és a command() hívás záró zárójele.
```
Ó, látom a problémát!
A `testsCmd` *egyszer* lett definiálva egy `.action` blokkkal, amely egy nagy `if/else if` struktúrát tartalmaz különböző műveletekhez, mint például `status`, `run`, `results`, `track`, `dashboard`, `push`, `docs`.

Ezután, a fő `action` blokkon *kívül*, vannak különálló `.command("status")`, `.command("run")`, `.command("results")` definíciók. Ez helytelen. A Commander.js azt várja, hogy az alparancsokat a fő parancs definíciójából *láncolják*, vagy külön definiálják a fő parancs *után*, de nem *az action-jének belsejében* ilyen módon.

A jelenlegi struktúra a következőket tartalmazza:
1.  Egy fő `testsCmd`, amely definiálja a `tests` parancsot és egy `action` -t, amely egy interaktív menüt jelenít meg.
2.  Majd különálló `testsCmd.command("status")`, `testsCmd.command("run")`, `testsCmd.command("results")` definíciók, amelyek új parancsokat definiálnak. Ez helyes, ha a `testsCmd` maga a *parancs objektum*, nem pedig az `action` metódus eredménye.

Újraértékeljük, hogyan kellene strukturálni a `testsCmd` -t.

Úgy tűnik, a `testsCmd` először így van definiálva:
```typescript
const testsCmd = program
  .command("tests")
  .description("Manage test scheduling and results")
  .action(async () => {
    // ... interactive menu code ...
  });
```
Ez azt jelenti, hogy a `testsCmd` egy `Command` példány, de már van egy action-je.

Ha alparancsokat szeretnék, akkor így kellene tennem:
```typescript
const testsCmd = program
  .command("tests")
  .description("Manage test scheduling and results"); // Kezdetben NINCS .action() itt

testsCmd.action(async () => { /* interaktív menü kód */ }); // Fő action külön definiálva

testsCmd
  .command("status")
  .description("Show test scheduler status and statistics")
  .action(async () => { /* status kód */ });

testsCmd
  .command("run")
  .description("Trigger a manual test run immediately")
  .action(async (options) => { /* run kód */ });

testsCmd
  .command("results [count]")
  .description("Show recent test run results")
  .action(async (count: string) => { /* results kód */ });
```
Ez a helyes Commander.js minta.

Tehát a 835. sorban lévő elemzési hiba, a `testsCmd.command("status")`, azért van, mert a `testsCmd` itt nem az a *parancskészítő*, amely elfogadja a `.command()` -t. Hanem a *lánc utolsó metódushívásának* eredménye, amely az `.action()` volt.

**A javítás a `testsCmd` definícióinak átstrukturálásával jár.**

1.  Távolítsa el a meglévő `.action` blokkot a `const testsCmd` definícióból.
2.  Helyezzen be egy új `.action` hívást a `testsCmd` számára, amely tartalmazza az interaktív menü logikát.
3.  Biztosítsa, hogy az ezt követő `.command()` hívások közvetlenül a `testsCmd` -ből legyenek láncolva.

**Pontosabban:**
Eredeti:
```typescript
const testsCmd = program
  .command("tests")
  .description("Manage test scheduling and results")
  .action(async () => {
    const { action } = await inquirer.prompt([
      // ... interaktív menü ...
    ]);
    // ... interaktív menü logika ...
  });

testsCmd // Itt fordul elő a hiba, mert az .action() már lezárta a láncot
  .command("status")
  // ...
```

Helyes struktúra:
```typescript
const testsCmd = program
  .command("tests")
  .description("Manage test scheduling and results");

// Definiálja az interaktív menü action-jét a fő 'tests' parancshoz
testsCmd.action(async () => {
    const { action } = await inquirer.prompt([
      // ... interaktív menü ...
    ]);
    // ... interaktív menü logika ...
  });

// Definiálja az alparancsokat a testsCmd-ből láncolva
testsCmd
  .command("status")
  .description("Show test scheduler status and statistics")
  .action(async () => {
    // ... status kód ...
  });
// ... egyéb alparancsok ...
```

Ez egy nagy változtatás lesz. Többlépéses tervet készítek.

**Lépések a `cli.ts` elemzési hibájának javításához:**
1.  Távolítsa el a meglévő `.action` blokkot a `const testsCmd` definícióból.
2.  Helyezzen be egy új `.action` hívást a `testsCmd` számára, amely tartalmazza az interaktív menü logikát.
3.  Biztosítsa, hogy az alparancsok (`status`, `run`, `results`) helyesen legyenek láncolva.

Először is el kell távolítanom az `.action` -t a fő `testsCmd` definícióból.
Az `.action` blokk a 835. soron kezdődik (az olvasott fájl jelenlegi számozásában). Nem, a 835. sor a `.command("status")`.
A fő `testsCmd` a 829. soron kezdődik.

```typescript
829 const testsCmd = program
830   .command("tests")
831   .description("Manage test scheduling and results")
832   .action(async () => { // <--- Ezt az action-t el kell mozdítani/törölni
833     const { action } = await inquirer.prompt([
834       {
835         type: "list",
836         name: "action",
// ...
919     }
  }); // <--- Ez az action és command lánc zárása
```
Tehát a most eltávolítandó blokk a 832. sorról a 919. sorig tart.

