      while (true) {
        const { code } = await inquirer.prompt([
          {
            type: "input",
            name: "code",
            message: ">>>",
          },
        ]);

        if (code === "exit") break;

        const result = await client.callTool("interpreter_run_python", {
          code,
        });
        // @ts-expect-error The result from interpreter_run_python might not have content[0].text.
