    const filePattern = new RegExp("(?:src|test|lib|app)\\/[^\\s:]+\\.(?:ts|tsx|js|jsx|py|go|rs)", "g");
    const matches = logs.match(filePattern);

    if (matches) {
      matches.forEach((match) => files.add(match));
    }

    return Array.from(files).slice(0, 5); // Top 5 files
